SELECT 
FROM shop_item
WHERE 1=1

	AND  shop_id = #{shopId}


	AND  item_name like CONCAT('%',#{itemName},'%')


	AND  item_category_1 = #{itemCategory1}


	AND  item_category_2 = #{itemCategory2}


	AND  item_category_3 = #{itemCategory3}


	AND  item_status = #{itemStatus}


	AND  item_type = #{itemType}

AND del_status = 0
ORDER BY id DESC

SELECT FROM shop_item WHERE 1=1
AND item_name like CONCAT('%',#{keyword},'%')
AND item_type = #{itemType}
AND item_status = 1 AND del_status = 0 ORDER BY sold_num DESC LIMIT #{offset}, #{pageSize}
